.ds-video-card {min-width: 0;
  cursor: pointer;}
.ds-card-picture {position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 8px;
  background: var(--dark, oklch(13% 0.005 270));
  isolation: isolate;}
.ds-card-open {position: absolute;
  inset: 0;
  width: 100%;
  padding: 0;
  border-radius: inherit;}
.ds-card-open:focus-visible {outline-offset: -3px;}
.ds-card-open-hint {position: absolute;
  bottom: 10px;
  right: 10px;
  display: flex;
  align-items: center;
  gap: 7px;
  border-radius: 5px;
  padding: 7px 9px;
  background: oklch(13% 0.005 270 / 0.9);
  font-size: 10.95px;
  color: var(--light, oklch(97% 0.003 270));
  opacity: 0;
  transition: opacity 140ms;}
.ds-video-card:hover .ds-card-open-hint,
.ds-card-open:focus-visible .ds-card-open-hint {opacity: 1;}
@media(max-width:560px){.ds-card-open-hint{opacity:1}}

.ds-specimen{font-family:"DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;font-size:15px;line-height:1.5;color:var(--ink, oklch(93% 0.006 270))}
