.ds-subtask-timeline {margin-top: 8px;}
.ds-subtask-rail {position: relative;
  height: 26px;}
.ds-subtask-rail::before {content: "";
  position: absolute;
  top: 11px;
  left: 0;
  right: 0;
  height: 5px;
  background: var(--subtle, oklch(25% 0.009 270));
  border-radius: 2px;}
.ds-subtask-segment {position: absolute;
  height: 26px;
  top: 0;
  padding: 0;}
.ds-subtask-segment > span {position: absolute;
  top: 11px;
  left: 1px;
  right: 1px;
  height: 5px;
  border-radius: 2px;
  background: oklch(46% 0.025 270);
  transition: background-color 140ms;}
.ds-subtask-segment:hover > span {background: var(--muted, oklch(73% 0.012 270));}
.ds-subtask-segment.ds-is-current > span {background: var(--accent, oklch(80% 0.09 280));}
.ds-subtask-segment:focus-visible {outline-offset: 0;
  border-radius: 3px;}
.ds-timeline-cursor {position: absolute;
  top: 7px;
  width: 2px;
  height: 13px;
  transform: translateX(-50%);
  background: var(--light, oklch(97% 0.003 270));
  border-radius: 1px;
  pointer-events: none;
  transition: left 160ms linear;}
@media(prefers-reduced-motion:reduce){.ds-timeline-cursor,.ds-subtask-segment>span{transition:none}}
